#include "dual_state_trainer.cuh"
#include <random>
#include <cstdio>
int main(){try{using namespace tao::dual;Config c;c.layers=1;c.d=4;c.s=2;c.m=3;c.e=8;c.vocab=261;CpuModel cpu(c);std::mt19937 rng(918);std::normal_distribution<float>d(0,.12f);for(auto&kv:cpu.w)for(auto&x:kv.second)x=kv.first.find("norm")!=std::string::npos?1.f:d(rng);GpuTrainer tr(cpu);auto before=tr.master.at("embedding")->host();float total=0;size_t supervised=0;for(int chunk=0;chunk<2;++chunk){for(int i=0;i<3;++i){auto y=tr.graph.step(17+chunk*3+i);bool mask=i!=0;total+=seed_loss(y,18+chunk*3+i,mask);supervised+=mask;}tr.graph.tape.backward();auto old=tr.graph.s[0]->value.host();tr.detach();if(old!=tr.graph.s[0]->value.host())throw std::runtime_error("detach state");}float norm=tr.update(supervised);auto after=tr.master.at("embedding")->host();if(before==after||tr.steps!=1)throw std::runtime_error("update");for(auto&kv:tr.graph.w)for(float g:kv.second->grad.host())if(g!=0)throw std::runtime_error("zero_grad");auto saved=after;tr.update(0);if(tr.steps!=1||saved!=tr.master.at("embedding")->host())throw std::runtime_error("empty update");printf("PASS GPU QAT step loss=%.7f supervised=%zu preclip_norm=%.7f detach/accumulate/empty-step checked\n",total/supervised,supervised,norm);return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
